PARAMS = {"SEL_COS": 0.97, "SEL_TEMP": 0.01, "FB_START": 140, "FB_GAIN": 0.0, "FB_DAMP": 0.05, "TRIM_MAX": 0.15,
          "FB_ALPHA": 0.3, "SEL_TRIM": 0.0, "FB_WRIST": 0.0, "PLAN_N": 16}
PARAM_BOUNDS = {"SEL_COS": (0.93, 0.99), "SEL_TEMP": (0.002, 0.05), "FB_START": (100, 190), "FB_GAIN": (0.0, 0.4),
                "FB_DAMP": (0.001, 0.5), "TRIM_MAX": (0.0, 0.4), "FB_ALPHA": (0.05, 1.0), "SEL_TRIM": (0.0, 1.0), "FB_WRIST": (0.0, 1.0), "PLAN_N": (0, 16)}

