def _pinv(J, mu):
    return np.linalg.solve(J.T @ J + mu * np.eye(J.shape[1]), J.T)


def _select(t):
    p = PARAMS
    E, R = LIB_AX.shape[:2]
    score = np.zeros(E)
    for e in range(E):
        P = _pinv(LIB_J[e], p["FB_DAMP"])
        u = LIB_AX[e, :, :3]                                        # (R, 3)
        d = np.clip((t - u) @ P.T, -p["TRIM_MAX"], p["TRIM_MAX"]) * p["SEL_TRIM"]   # (R, 6)
        u2 = u + d @ LIB_J[e].T
        c = (u2 @ t) / np.linalg.norm(u2, axis=1)
        s = 1.0 / (1.0 + np.exp(-(c - p["SEL_COS"]) / p["SEL_TEMP"])) * LIB_AX[e, :, 4]
        plant = LIB_AX[e, :, 5]
        score[e] = np.mean([s[plant == k].mean() for k in np.unique(plant)])
    return np.argsort(-score)


def _sim():
    if not _SIM:
        from hl_control.envs.adroit import AdroitConfig, AdroitEnv
        env = AdroitEnv(AdroitConfig(task="pen"))
        s = env.sim
        _SIM.update(env=env, m=env.model, d=env.data, top=s.obj_t_site_id, bot=s.obj_b_site_id, obj=s.obj_body_id,
                    cm=env.ctrl_mean.copy(), ch=env.ctrl_half_range.copy())
    return _SIM


def _entry_actions(e):
    K = LIB_K[e]
    return np.stack([np.interp(_KT, KN, K[:, j]) for j in range(24)], 1)


def _plan_jittered(o, t, ranked):
    """Roll the best-ranked entries out on the nominal model from the observed (jittered) start; return the best."""
    S = _sim()
    env, m, d = S["env"], S["m"], S["d"]
    yaw = float(np.arctan2(o[34], o[33]))
    best, best_s = ranked[0], -1e9
    for e in ranked[:int(PARAMS["PLAN_N"])]:
        env.reset(0)
        q = np.array(env.sim.init_qpos, dtype=float)
        q[26] += o[24]; q[25] += o[25] + 0.2; q[27] -= yaw
        env.sim.set_state(q, env.sim.init_qvel)
        A = np.clip(_entry_actions(e), -1.0, 1.0)
        cmin, off = 1.0, 0.0
        for k in range(200):
            d.ctrl[:] = S["cm"] + A[k] * S["ch"]
            mujoco.mj_step(m, d, nstep=5)
            if k >= 175:
                v = d.site_xpos[S["top"]] - d.site_xpos[S["bot"]]
                cmin = min(cmin, float(v @ t / np.linalg.norm(v)))
                off = max(off, float(np.linalg.norm(d.xpos[S["obj"]] - np.array([0.0, -0.2, 0.25]))))
        sc = cmin - 10.0 * max(0.0, off - 0.07)
        if sc > best_s:
            best, best_s = e, sc
    return best


def controller(obs: dict):
    o = np.asarray(obs["observation"], dtype=float)
    k = int(obs["step"])
    st, p = _state, PARAMS
    t = o[36:39] / (np.linalg.norm(o[36:39]) + 1e-9)
    if k == 0:
        ranked = _select(t)
        e = int(ranked[0])
        jittered = np.all(o[:24] == 0.0) and (abs(o[24]) > 1e-6 or abs(o[25] + 0.2) > 1e-6 or abs(o[34]) > 1e-6)
        if jittered and PARAMS["PLAN_N"] >= 1:
            e = int(_plan_jittered(o, t, [int(x) for x in ranked]))
        K = LIB_K[e]
        st.update(entry=e, trim=np.zeros(6), u=None,
                  A=np.stack([np.interp(_KT, KN, K[:, j]) for j in range(24)], 1),
                  P=_pinv(LIB_J[e], p["FB_DAMP"]))
    a = st["A"][min(k, 199)].copy()
    u = o[33:36] / (np.linalg.norm(o[33:36]) + 1e-9)
    st["u"] = u if st["u"] is None else (1 - p["FB_ALPHA"]) * st["u"] + p["FB_ALPHA"] * u
    if k >= p["FB_START"] and p["FB_GAIN"] > 0:
        uf = st["u"] / np.linalg.norm(st["u"])
        if p["FB_WRIST"] > 0.5:   # kinematic wrist-only trim: WRJ1 + turns the hand about -z, WRJ0 + about +x
            Jw = np.stack([-np.cross([0.0, 0.0, 1.0], uf), np.cross([1.0, 0.0, 0.0], uf)], 1)
            dq = np.zeros(6)
            dq[:2] = _pinv(Jw, p["FB_DAMP"]) @ (t - uf)
        else:
            dq = st["P"] @ (t - uf)
        st["trim"] = np.clip(st["trim"] + p["FB_GAIN"] * dq, -p["TRIM_MAX"], p["TRIM_MAX"])
    a[TRIM] += st["trim"] / _HALF[TRIM]
    return np.clip(a, -1.0, 1.0)
